import 'package:jirani_domain/jirani_domain.dart';
import 'package:test/test.dart';

// Generated by the API (apps/ledger/anchoring.py) for three chains; the phone must
// reach the same root from the same leaf and path.
const root = 'b3115e6d26f962aee04fd72f33de922633a0ff3f999a8681e394fab7c9d2b3f9';
const path = [
  {'side': 'left', 'hash': 'c60ffa2952f30af070f671f1a0ab8b0f346304c35a04df50ffbe13af6315dca8'},
  {'side': 'right', 'hash': '0f775302c0ff85221a769f75581ec815a50eed5d5f63b0602a8b7b24267d6302'},
];

void main() {
  test('the leaf matches the server', () {
    expect(anchorLeaf('22222222-2222-2222-2222-222222222222', 7, 'bb' * 32),
        '67888b8a74d419c79277d1d07546c41d1154a45d750a15c61a3aa5e0cb8879a0');
  });

  test('the path reaches the root', () {
    final leaf = anchorLeaf('22222222-2222-2222-2222-222222222222', 7, 'bb' * 32);
    expect(verifyAnchorPath(leaf, path, root), isTrue);
  });

  test('a different head does not', () {
    final forged = anchorLeaf('22222222-2222-2222-2222-222222222222', 7, 'cc' * 32);
    expect(verifyAnchorPath(forged, path, root), isFalse);
  });
}
